values
  ('00000000-0000-4000-8000-000000000010', 'ipd', 'iphone-duo', 'apple', 'smartphones', 'iPhone Duo', 'Le premier iPhone pliable : un écran de 7,6 pouces qui se referme dans la poche.', 'Un grand écran qui se déplie, un écran externe pour le quotidien, en titane poli.', 'phone', '2026-10-23', '2027-01-21', 12, array['ios']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000001', 'ip18', 'iphone-18-pro', 'apple', 'smartphones', 'iPhone 18 Pro', 'Puce A20 Pro, ouverture variable et nouvelle finition bordeaux.', 'Le plus avancé des iPhone Pro. Désormais en bordeaux.', 'phone', '2026-09-10', '2026-12-09', 12, array['ios']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000011', 'ip17', 'iphone-17', 'apple', 'smartphones', 'iPhone 17', 'L''iPhone de référence, avec un écran ProMotion 120 Hz et deux caméras 48 Mpx.', 'Un écran plus fluide, deux caméras Fusion et la puce A19, pour tous les jours.', 'phone', '2025-09-19', '2025-12-18', 12, array['ios']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000012', 'ip17e', 'iphone-17e', 'apple', 'smartphones', 'iPhone 17e', 'L''essentiel de l''iPhone à petit prix, avec la puce A19 et 256 Go dès l''entrée de gamme.', 'La puce A19, une caméra Fusion 48 Mpx et MagSafe, dans un format de 6,1 pouces.', 'phone', '2026-03-11', '2026-06-09', 12, array['ios']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000013', 'zf8', 'galaxy-z-fold8', 'samsung', 'smartphones', 'Galaxy Z Fold8', 'Un smartphone qui se déplie en tablette de 7,6 pouces, avec un écran externe de 5,5 pouces pour l''usage au quotidien.', 'Une tablette dans la poche : 4,5 mm d''épaisseur une fois déplié, 201 g.', 'phone', '2026-08-07', '2026-11-05', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000014', 's26u', 'galaxy-s26-ultra', 'samsung', 'smartphones', 'Galaxy S26 Ultra', 'Le très haut de gamme Samsung : capteur 200 Mpx, S Pen intégré et écran qui masque votre contenu aux regards indiscrets.', 'Un grand écran de 6,9 pouces, un S Pen intégré et quatre appareils photo.', 'phone', '2026-03-11', '2026-06-09', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000015', 'zfl8', 'galaxy-z-flip8', 'samsung', 'smartphones', 'Galaxy Z Flip8', 'Le pliant à clapet qui tient dans toutes les poches, avec un écran externe de 4,1 pouces pour les selfies et les notifications.', 'Un écran de 6,9 pouces qui se replie en carré, et l''écran FlexWindow devant.', 'phone', '2026-08-07', '2026-11-05', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000016', 's26', 'galaxy-s26', 'samsung', 'smartphones', 'Galaxy S26', 'Le haut de gamme compact de Samsung : 6,3 pouces, 167 g et Galaxy AI, pour tout faire d''une seule main.', 'Un format compact, un écran de 6,3 pouces et la puce Exynos 2600.', 'phone', '2026-03-11', '2026-06-09', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000002', 'a57', 'galaxy-a57-5g', 'samsung', 'smartphones', 'Galaxy A57 5G', '6,9 mm de finesse. Six ans de mises à jour.', 'Un écran généreux et une finesse pensée pour le quotidien.', 'phone', '2026-03-20', '2026-06-18', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000017', 'x17u', 'xiaomi-17-ultra', 'xiaomi', 'smartphones', 'Xiaomi 17 Ultra', 'Le photophone de Xiaomi : capteur Leica 1 pouce et téléobjectif 200 Mpx à zoom optique 75-100 mm.', 'Une optique Leica de 1 pouce, un téléobjectif 200 Mpx et 6 000 mAh.', 'phone', '2026-02-01', '2026-05-02', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000018', 'x17', 'xiaomi-17', 'xiaomi', 'smartphones', 'Xiaomi 17', 'Le haut de gamme compact de Xiaomi : 6,3 pouces, une optique Leica et une batterie de 6 330 mAh dans 191 g.', 'Une optique Leica Summilux et une grande batterie dans un format compact.', 'phone', '2026-02-01', '2026-05-02', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000019', 'x17tp', 'xiaomi-17t-pro', 'xiaomi', 'smartphones', 'Xiaomi 17T Pro', 'Le spécialiste du téléobjectif : zoom optique x5 Leica, puce Dimensity 9500 et une batterie de 7 000 mAh.', 'Un téléobjectif x5 Leica, un écran 144 Hz et une très grande batterie.', 'phone', '2026-05-01', '2026-07-30', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000003', 'rn15', 'redmi-note-15-pro-plus-5g', 'xiaomi', 'smartphones', 'Redmi Note 15 Pro+ 5G', 'Charge 100 W et robustesse renforcée.', 'Une charge rapide et un format polyvalent, à prix indicatif.', 'phone', '2026-01-15', '2026-04-15', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000020', 'apm2', 'airpods-max-2', 'apple', 'ecouteurs', 'AirPods Max 2', 'Le casque circum-auriculaire d''Apple, désormais avec la puce H2 et un son sans perte en USB-C.', 'Un casque à réduction de bruit active, avec audio sans perte par USB-C.', 'buds', '2026-04-01', '2026-06-30', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000021', 'app3', 'airpods-pro-3', 'apple', 'ecouteurs', 'AirPods Pro 3', 'La meilleure réduction de bruit intra-auriculaire d''Apple, avec suivi du cœur pendant le sport.', 'Une réduction de bruit renforcée et un capteur de fréquence cardiaque.', 'buds', '2025-09-19', '2025-12-18', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000004', 'ap5', 'airpods-5', 'apple', 'ecouteurs', 'AirPods 5', 'La réduction de bruit active, désormais sur les AirPods.', 'Un format compact avec réduction de bruit active.', 'buds', '2026-09-10', '2026-12-09', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000022', 'gb4p', 'galaxy-buds4-pro', 'samsung', 'ecouteurs', 'Galaxy Buds4 Pro', 'Le haut de gamme audio Samsung : réduction de bruit adaptative, son 24 bits et deux haut-parleurs par écouteur.', 'Un woofer et un tweeter dans chaque écouteur, et six microphones.', 'buds', '2026-03-11', '2026-06-09', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000005', 'gb4', 'galaxy-buds4', 'samsung', 'ecouteurs', 'Galaxy Buds4', 'Un design repensé pour un maintien parfait.', 'Des écouteurs conçus pour accompagner votre journée.', 'buds', '2026-02-25', '2026-05-26', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000023', 'xb6', 'xiaomi-buds-6', 'xiaomi', 'ecouteurs', 'Xiaomi Buds 6', 'Des écouteurs semi-intra confortables, réglés par Harman, avec l''audio sans perte aptX Lossless.', 'Un format semi-intra, une réduction de bruit par IA et l''audio sans perte.', 'buds', '2026-05-01', '2026-07-30', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000024', 'rb8', 'redmi-buds-8', 'xiaomi', 'ecouteurs', 'Redmi Buds 8', 'Des intra-auriculaires abordables, avec une réduction active du bruit jusqu''à 50 dB et 44 heures d''écoute.', 'L''entrée de gamme audio de Xiaomi, avec réduction de bruit et boîtier de charge.', 'buds', '2026-06-01', '2026-08-30', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000025', 'awu4', 'apple-watch-ultra-4', 'apple', 'montres', 'Apple Watch Ultra 4', 'La montre de sport et d''aventure d''Apple : titane, 3 000 nits et jusqu''à 50 h d''autonomie.', 'Un boîtier en titane de 49 mm, la 5G et la connexion satellite d''urgence.', 'watch', '2026-09-18', '2026-12-17', 12, array['ios']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000006', 'aw12', 'apple-watch-series-12', 'apple', 'montres', 'Apple Watch Series 12', 'Nouveaux capteurs santé. 15 min de charge pour 12 h.', 'Une montre connectée avec de nouveaux capteurs santé.', 'watch', '2026-09-10', '2026-12-09', 12, array['ios']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000026', 'awse3', 'apple-watch-se-3', 'apple', 'montres', 'Apple Watch SE 3', 'Les fonctions santé essentielles de l''Apple Watch à un prix accessible.', 'Un écran toujours activé, la puce S10 et l''étanchéité pour la natation.', 'watch', '2025-09-19', '2025-12-18', 12, array['ios']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000027', 'gwu2', 'galaxy-watch-ultra2', 'samsung', 'montres', 'Galaxy Watch Ultra2', 'La montre aventurière de Samsung : boîtier en titane, 4G, GPS bi-fréquence et jusqu''à 80 heures d''autonomie.', 'Un boîtier en titane de 47 mm, la 4G et un GPS bi-fréquence.', 'round', '2026-08-07', '2026-11-05', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000007', 'gw9', 'galaxy-watch9', 'samsung', 'montres', 'Galaxy Watch9', 'Puce Snapdragon Wear Elite. En 40 et 44 mm.', 'Une montre Galaxy disponible en deux tailles.', 'round', '2026-07-15', '2026-10-13', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000028', 'xws5', 'xiaomi-watch-s5', 'xiaomi', 'montres', 'Xiaomi Watch S5', 'Une montre élégante en acier inoxydable, avec un écran AMOLED très lumineux, le paiement NFC et 14 jours d''autonomie.', 'Un boîtier en acier de 46 mm, le GNSS intégré et le paiement sans contact.', 'round', '2026-05-01', '2026-07-30', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000008', 'rw6', 'redmi-watch-6', 'xiaomi', 'montres', 'Redmi Watch 6', 'Grand écran AMOLED, jusqu’à 24 jours d’autonomie.', 'Une montre connectée à grand écran et longue autonomie.', 'watch', '2026-01-10', '2026-04-10', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000029', 'gf3', 'galaxy-fit3', 'samsung', 'bracelets', 'Galaxy Fit3', 'Le bracelet d''activité léger de Samsung : grand écran AMOLED de 1,6 pouce, plus de 100 sports et 13 jours d''autonomie.', 'Un bracelet léger, avec suivi du sommeil, du stress et détection de chute.', 'band', '2024-02-21', '2024-05-21', 12, array['android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000030', 'sb10p', 'xiaomi-smart-band-10-pro', 'xiaomi', 'bracelets', 'Xiaomi Smart Band 10 Pro', 'Le bracelet sportif de Xiaomi : écran AMOLED de 1,74 pouce, GNSS intégré et jusqu''à 21 jours d''autonomie.', 'Un cadre en aluminium, un GNSS intégré et plus de 150 modes sport.', 'band', '2026-05-01', '2026-07-30', 12, array['ios', 'android']::text[], array[]::text[], false),
  ('00000000-0000-4000-8000-000000000009', 'sb10', 'xiaomi-smart-band-10', 'xiaomi', 'bracelets', 'Xiaomi Smart Band 10', 'Léger et discret, il suit votre journée.', 'Un bracelet léger pour le suivi des activités du quotidien.', 'band', '2025-08-27', '2025-11-25', 12, array['ios', 'android']::text[], array[]::text[], false)
